def executar(raiz, rotulo, comando, ambiente, relatorio):
    print("Executando "+rotulo+"...",flush=True)
    resultado=subprocess.run(comando,cwd=raiz,env=ambiente,capture_output=True,text=True,encoding="utf-8",errors="replace")
    saida=resultado.stdout+resultado.stderr
    print(saida, end="" if saida.endswith("\n") else "\n",flush=True)
    relatorio[rotulo]={"return_code":resultado.returncode,"saida":saida}
    print(rotulo.upper()+"_RETURN_CODE="+str(resultado.returncode),flush=True)
    if resultado.returncode: raise RuntimeError("A etapa "+rotulo+" falhou; confira o relatório.")


def criar_acessos(raiz,nomes,criados):
    from backend.app.core.armazenamento_acesso import ArmazenamentoAcesso
    destino=seguro(raiz,BANCO_ACESSO); privado=seguro(raiz,CREDENCIAIS)
    if destino.exists():
        servico=ArmazenamentoAcesso(destino)
        contas=servico.listar_usuarios()
        if not any(c["role"]=="admin" and c["ativo"] for c in contas):
            raise RuntimeError("O banco de acesso existente não tem administrador ativo; use GERIR_CONTAS para conferir.")
        print("CONTAS_EXISTENTES_PRESERVADAS=True",flush=True)
        return False
    if privado.exists(): raise RuntimeError("Há credenciais iniciais sem o banco de acesso; arquivo preservado.")
    destino.parent.mkdir(parents=True,exist_ok=True)
    temporario=destino.with_name("mec_acessos_preparacao_"+secrets.token_hex(6)+".db")
    criados.append(temporario)
    servico=ArmazenamentoAcesso(temporario); servico.inicializar()
    linhas=["MEC-Serviços D30 — ACESSOS INICIAIS LOCAIS", "Não envie este arquivo ao Git nem anexe à conversa.",
        "Entre na aplicação, altere a senha inicial em Minha conta e entre novamente.",
        "A administração entrega as credenciais de cliente/fornecedor apenas aos respectivos titulares.", ""]
    for nome,email,perfil,empresa in (("Administrador","admin@mec-servicos.local","admin",None),
        (nomes["cliente"],"cliente@mec-servicos.local","cliente",2),(nomes["fornecedor"],"fornecedor@mec-servicos.local","fornecedor",4)):
        senha=secrets.token_urlsafe(24)
        servico.criar_usuario(nome,email,perfil,empresa,senha)
        linhas += ["PERFIL="+perfil, "EMAIL="+email, "SENHA_INICIAL="+senha, "EMPRESA_ID="+str(empresa), ""]
    # Não sobrescreve contas/credenciais que possam ter sido criadas em paralelo.
    with privado.open("x",encoding="utf-8",newline="\n") as arquivo:
        criados.append(privado); arquivo.write("\n".join(linhas)+"\n")
    os.chmod(privado,0o600); os.chmod(temporario,0o600)
    if destino.exists(): raise RuntimeError("O banco de acesso foi criado por outro processo; instalação interrompida.")
    # O link é atômico e falha se o destino existir (NTFS e sistemas de arquivos usuais).
    os.link(temporario,destino); criados.append(destino); temporario.unlink()
    print("CONTAS_INICIAIS_CRIADAS=3",flush=True)
    print("TROCA_SENHA_INICIAL_OBRIGATORIA=True",flush=True)
    print("CREDENCIAIS_LOCAIS="+str(privado),flush=True)
    return True


def salvar_relatorio(raiz,relatorio):
    dados=raiz/(STEM+".json"); texto=raiz/(STEM+".txt")
    dados.write_text(json.dumps(relatorio,ensure_ascii=False,indent=2)+"\n",encoding="utf-8")
    linhas=["MEC-Serviços D30 — Acesso no servidor e perfis", "REVISION="+REVISION]
    for chave,valor in relatorio.items():
        if not isinstance(valor,dict): linhas.append(chave.upper()+"="+str(valor))
    for etapa in ("validacao_rotas","pytest","npm_build"):
        if etapa in relatorio:linhas.extend(["",etapa.upper()+":",relatorio[etapa]["saida"]])
    texto.write_text("\n".join(linhas).rstrip()+"\n",encoding="utf-8")
    print("RELATORIO="+str(texto)); print("JSON="+str(dados))


def main() -> int:
    print("MEC-Serviços D30 — Acesso no servidor e permissões por perfil",flush=True)
    print("REVISION="+REVISION,flush=True)
    raiz=None; backup=None; originais={}; criados=[]; alterados=[]; pastas_novas=[]; dist_existia=False
    relatorio={"revision":REVISION,"resultado":"ERRO","restaurado":False,"intermediacao_logistica_implantada":False}
    try:
        if sys.version_info<(3,10):raise RuntimeError("Use Python 3.10 ou mais recente.")
        raiz=localizar_raiz();print("ROOT="+str(raiz),flush=True);relatorio["raiz"]=str(raiz)
        urls=git(raiz,"remote","get-url","--all","origin").splitlines()
        if not urls or not all(origem_mec(url.strip()) for url in urls):raise RuntimeError("Origin não corresponde ao MEC-Servicos informado.")
        print("ORIGIN_MEC_CONFIRMADO=True",flush=True)
        if git(raiz,"ls-files","--",str(BANCO_ACESSO).replace("\\","/"),str(CREDENCIAIS).replace("\\","/")):
            raise RuntimeError("Um arquivo privado de acesso já está rastreado no Git. Retire-o do índice antes de continuar.")
        diagnostico=raiz/"MEC_SERVICOS_V0_1_D29_DIAGNOSTICO_INTERMEDIACAO_ADMIN_RELATORIO.json"
        dados=json.loads(diagnostico.read_text(encoding="utf-8-sig"))
        if dados.get("resultado")!="OK" or dados.get("contrato",{}).get("contato_direto_cliente_fornecedor") is not False:
            raise RuntimeError("O diagnóstico D29 e o contrato administrativo não conferem.")
        for nome,esperado in BASE_SHA256.items():
            grupo="backend" if nome.startswith("backend/") else "frontend"
            if dados.get(grupo,{}).get("sha256_fontes",{}).get(nome)!=esperado:
                raise RuntimeError("O diagnóstico D29 não corresponde aos fontes enviados: "+nome)
        pacote=json.loads((raiz/"frontend/package.json").read_text(encoding="utf-8-sig"))
        if not pacote.get("scripts",{}).get("build") or "axios" not in pacote.get("dependencies",{}):
            raise RuntimeError("Confira build e Axios no frontend.")
        npm=shutil.which("npm.cmd" if os.name=="nt" else "npm")
        if not npm:raise RuntimeError("npm não encontrado.")
        if os.environ.get("MEC_ACESSOS_DB"):
            configurado=Path(os.environ["MEC_ACESSOS_DB"])
            if not configurado.is_absolute():configurado=raiz/configurado
            if configurado.resolve()!=(raiz/BANCO_ACESSO).resolve():
                raise RuntimeError("MEC_ACESSOS_DB aponta para outro destino. Use o banco de acesso local preparado para este D30.")
        banco,nomes,antes=verificar_banco_negocio(raiz)
        seguro(raiz,BANCO_ACESSO); seguro(raiz,CREDENCIAIS)
        plano=plano_arquivos(raiz)
        for nome,conteudo in plano.items():
            if nome.endswith(".py"):ast.parse(conteudo.decode("utf-8-sig"),filename=nome)
        print("CONTRATO_D29_E_FONTES_OK=True",flush=True)
        print("BANCO_NEGOCIO_SOMENTE_LEITURA=True",flush=True)
        backup=raiz/"_mec_backups"/("D30_ACESSO_SERVIDOR_"+datetime.now().strftime("%Y%m%d_%H%M%S_%f"));backup.mkdir(parents=True)
        relatorio["backup"]=str(backup);print("BACKUP_DIR="+str(backup),flush=True)
        dist=seguro(raiz,"frontend/dist");dist_existia=dist.exists()
        if dist.is_symlink():raise RuntimeError("O build não pode ser um destino simbólico.")
        if dist_existia:shutil.copytree(dist,backup/"frontend_dist")
        for nome in plano:
            alvo=raiz/nome;originais[nome]=alvo.read_bytes() if alvo.exists() else None
            if originais[nome] is not None:
                destino=backup/"originais"/nome;destino.parent.mkdir(parents=True,exist_ok=True);destino.write_bytes(originais[nome])
            for pasta in alvo.parents:
                if pasta==raiz:break
                if not pasta.exists() and pasta not in pastas_novas:pastas_novas.append(pasta)
        (backup/"MANIFESTO.json").write_text(json.dumps({n:None if v is None else sha(v) for n,v in originais.items()},indent=2)+"\n")
        for nome,conteudo in plano.items():
            alvo=raiz/nome;alvo.parent.mkdir(parents=True,exist_ok=True);alterados.append(nome);alvo.write_bytes(conteudo)
        print("ARQUIVOS_D30_APLICADOS="+str(len(plano)),flush=True)
        with tempfile.TemporaryDirectory(prefix="mec_d30_testes_") as temporario:
            ambiente=parametros_testes(Path(temporario))
            executar(raiz,"validacao_rotas",[sys.executable,"-c",VALIDACAO_ROTAS],ambiente,relatorio)
            print("TESTES_PERMISSOES_SEM_OVERRIDE=True",flush=True)
            print("TESTES_NEGOCIO_LEGADOS=Contexto administrativo somente nos arquivos com hash registrado",flush=True)
            executar(raiz,"pytest",[sys.executable,"-m","pytest","tests","-q","--ignore=tests/mold"],ambiente,relatorio)
            executar(raiz/"frontend","npm_build",[npm,"run","build"],ambiente,relatorio)
        _,_,depois=verificar_banco_negocio(raiz)
        if antes!=depois:raise RuntimeError("O banco de negócio mudou durante a instalação. Nenhum histórico será sobrescrito.")
        print("HISTORICO_NEGOCIO_PRESERVADO=True",flush=True)
        relatorio["contas_iniciais_criadas"]=criar_acessos(raiz,nomes,criados)
        relatorio.update({"resultado":"OK","arquivos_alterados":alterados,"autenticacao_servidor_implantada":True,
            "historico_preservado":True,"contato_direto_permitido":False,"painel_logistico_administrativo":"PROXIMA_ETAPA"})
        salvar_relatorio(raiz,relatorio)
        print("RESULTADO=OK",flush=True)
        print("Reinicie o backend e atualize a aplicação com Ctrl+F5.",flush=True)
        if relatorio["contas_iniciais_criadas"]:
            print("Abra localmente data/MEC_SERVICOS_D30_ACESSOS_INICIAIS.txt; altere cada senha no primeiro acesso.",flush=True)
        else:
            print("Use as contas existentes; nenhuma senha foi alterada por esta execução.",flush=True)
        print("Administração: use /conta para criar, ativar/desativar e redefinir acessos.",flush=True)
        print("O painel de material, coleta e qualidade será implantado na próxima etapa.",flush=True)
        return 0
    except Exception as erro:
        relatorio["erro"]=str(erro);print("ERRO="+str(erro),flush=True)
        if raiz and (alterados or criados):
            problemas=[]
            for nome in reversed(alterados):
                try:
                    if originais[nome] is None:(raiz/nome).unlink(missing_ok=True)
                    else:(raiz/nome).write_bytes(originais[nome])
                except OSError as restauracao:problemas.append(str(restauracao))
            if "npm_build" in relatorio:
                try:
                    if dist.exists():shutil.rmtree(dist)
                    if dist_existia:shutil.copytree(backup/"frontend_dist",dist)
                except OSError as restauracao:problemas.append(str(restauracao))
            for p in reversed(criados):
                try:p.unlink(missing_ok=True)
                except OSError as restauracao:problemas.append(str(restauracao))
            for p in sorted(pastas_novas,key=lambda item:len(item.parts),reverse=True):
                if p.exists() and not any(p.iterdir()):p.rmdir()
            relatorio["restaurado"]=not problemas
            if problemas:relatorio["falhas_restauracao"]=problemas
            print("RESTAURADO="+str(relatorio["restaurado"]),flush=True)
        if raiz:
            try:salvar_relatorio(raiz,relatorio)
            except OSError:print("RELATORIO_NAO_GRAVADO=True")
        print("RESULTADO=ERRO",flush=True);return 1


if __name__ == "__main__":
    raise SystemExit(main())
